def icon(name, size=20, color="#4F6BD3"):
    return (
        f'<svg class="ico" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="{color}" '
        f'stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{_ICON_BODY[name]}</svg>'
    )


