def ensure_theme_file():
    """밝은 테마 설정 파일(.streamlit/config.toml)이 없으면 만들어요. 적용하려면 앱을 한 번 다시 실행해야 해요."""
    path = os.path.join(os.getcwd(), ".streamlit", "config.toml")
    if os.path.exists(path):
        return False
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            f.write(THEME_TOML)
        return True
    except Exception:
        return False


def apply_light_theme_runtime():
    """실행 중인 앱에 밝은 테마 값을 넣어요. 브라우저를 새로고침(F5)하면 적용돼요."""
    try:
        for k, v in {"base": "light", "primaryColor": "#4F6BD3", "backgroundColor": "#F4F6FD",
                     "secondaryBackgroundColor": "#FFFFFF", "textColor": "#0F172A"}.items():
            st._config.set_option(f"theme.{k}", v)
    except Exception:
        pass


