def load_json(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return []


def save_json(path, data):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)


# ============ 의사용 플랫폼 연동 ============
# 공유 폴더 파일 규칙
#  consultation_req.txt  환자 앱이 한 줄씩 추가(날짜|시간|사유), 의사용이 수락하면 그 줄을 지움
#  appointments.json     환자 앱이 요청 저장, 의사용이 확정(status=confirmed)하거나 일정을 직접 등록
#  alerts.json           위험 알림 (의사용이 확인하면 status=acknowledged)
#  checkins.json         마음 돌아보기(PHQ-9) 기록
#  bio_report.json       일주기·HRV·바이오마커·위험 요인 리포트
#  patient_profile.json  이름·만 나이·성별·키·몸무게 (환자가 입력한 것만)
#  diagnosis_report.json 의사용이 "진단 결과 확정 및 환자 플랫폼 전송"을 누르면 저장 (환자 앱이 읽음)
REQ_FILE = os.path.join(SHARED_DIR, "consultation_req.txt")
PROFILE_FILE = os.path.join(SHARED_DIR, "patient_profile.json")
REPORT_FILE = os.path.join(SHARED_DIR, "diagnosis_report.json")
SEEN_FILE = os.path.join(BASE_DIR, "seen_events.json")       # 환자가 '확인'한 알림 (이 앱에서만 사용)


def load_dict(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def read_req_lines():
    try:
        with open(REQ_FILE, "r", encoding="utf-8") as f:
            return [ln.strip() for ln in f.read().split("\n") if ln.strip()]
    except Exception:
        return []


def append_request(date_iso, time_str, reason):
    """의사용 플랫폼의 '실시간 상담 요청'에 뜨는 한 줄을 추가해요. 형식: 날짜|시간|사유"""
    clean = re.sub(r"[|\r\n]+", " ", reason).strip()[:100]
    line = f"{date_iso}|{time_str}|{clean}"
    with open(REQ_FILE, "a", encoding="utf-8") as f:
        f.write(line + "\n")
    return line


def appt_status(a, req_lines=None):
    """의사용이 수락하면 status가 confirmed가 되거나, 요청 파일에서 그 줄이 사라져요."""
    if a.get("status") == "confirmed":
        return "confirmed"
    line = a.get("req_line")
    if line:
        lines = req_lines if req_lines is not None else read_req_lines()
        try:
            age = (datetime.now() - datetime.strptime(a["created"], "%Y-%m-%d %H:%M:%S")).total_seconds()
        except Exception:
            age = 0
        if line not in lines and age > 4:
            return "confirmed"
    return "requested"


def publish_profile():
    """환자가 입력한 정보를 의사용 화면의 '환자 프로필'로 보내요. (입력하지 않은 항목은 비워둠)"""
    def num(key):
        v = st.session_state.get(key) or 0
        return int(v) if v else None
    prof = {"name": PATIENT["name"], "age": num("user_age"), "sex": st.session_state.get("user_sex") or None,
            "height_cm": num("user_height"), "weight_kg": num("user_weight")}
    sig = json.dumps(prof, sort_keys=True, ensure_ascii=False)
    if sig == st.session_state.get("profile_sig") and _time.time() - st.session_state.get("profile_pub_t", 0) < 20:
        return
    data = load_dict(PROFILE_FILE)
    prof["updated"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")      # 가장 최근에 사용한 환자가 '연동 환자'
    data[PATIENT["id"]] = prof
    with open(PROFILE_FILE, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    st.session_state.profile_sig = sig
    st.session_state.profile_pub_t = _time.time()


def latest_report():
    reports = load_dict(REPORT_FILE).get(PATIENT["id"], [])
    return reports[-1] if isinstance(reports, list) and reports else None


def collect_events():
    """의사용 플랫폼에서 온 변화: 상담 확정, 알림 확인, 새 진료 소견"""
    events = []
    req_now = read_req_lines()
    today = date.today().isoformat()
    for a in load_json(APPTS_FILE):
        if a.get("patient_id") != PATIENT["id"] or a.get("date", "") < today:
            continue
        if appt_status(a, req_now) == "confirmed":
            if a.get("source") == "의료진 등록":
                what = a.get("kind") or "진료"
                text = f"담당 의료진이 {a['date']} {a.get('time', '')} {what} 일정을 등록했어요.".replace("  ", " ")
            else:
                text = f"담당 의료진이 {a['date']} {a.get('time', '')} 상담을 확정했어요."
            events.append({"id": f"appt:{a['id']}", "kind": "success", "text": text})
    acked = [a for a in load_json(ALERTS_FILE) if a.get("patient_id") == PATIENT["id"] and a.get("status") == "acknowledged"]
    if acked:
        a = acked[-1]
        events.append({"id": f"ack:{a['id']}", "kind": "info", "text": "담당 의료진이 알림을 확인했어요. 필요하면 곧 연락드릴게요."})
    rep = latest_report()
    if rep:
        events.append({"id": f"report:{rep.get('report_id')}", "kind": "info",
                       "text": "새 진료 소견이 도착했어요. '내 상태 > 소견'에서 확인해 보세요."})
    return events


def dismiss_event(event_id):
    seen = load_dict(SEEN_FILE)
    lst = seen.setdefault(PATIENT["id"], [])
    if event_id not in lst:
        lst.append(event_id)
    with open(SEEN_FILE, "w", encoding="utf-8") as f:
        json.dump(seen, f, ensure_ascii=False)


def link_signature():
    """의사용 플랫폼이 바꿀 수 있는 파일의 상태. 바뀌면 화면을 새로 고쳐요."""
    parts = []
    for p in (REQ_FILE, APPTS_FILE, REPORT_FILE, ALERTS_FILE):
        try:
            stt = os.stat(p)
            parts.append((os.path.basename(p), int(stt.st_mtime * 1000), stt.st_size))
        except OSError:
            parts.append((os.path.basename(p), 0, 0))
    return str(parts)


def demo_doctor_accept():
    """(시연용) 의사용 플랫폼이 수락한 것처럼 요청을 지우고 확정 처리"""
    try:
        open(REQ_FILE, "w", encoding="utf-8").close()
    except Exception:
        pass
    appts = load_json(APPTS_FILE)
    for a in appts:
        if a.get("patient_id") == PATIENT["id"] and a.get("status") != "confirmed":
            a["status"] = "confirmed"
    save_json(APPTS_FILE, appts)
    alerts = load_json(ALERTS_FILE)
    for a in alerts:
        if a.get("patient_id") == PATIENT["id"] and a.get("priority") == "urgent":
            a["status"] = "acknowledged"
    save_json(ALERTS_FILE, alerts)


