# ============ AI 응답에서 글자만 꺼내기 ============
def get_text(response):
    """응답 블록 중 글자(text) 블록만 모아서 반환 (생각 블록은 건너뜀)"""
    return "".join(
        getattr(block, "text", "") for block in response.content
        if getattr(block, "type", "") == "text"
    ).strip()


