def assess_keyword(history):
    """규칙 기반 1단 감지"""
    user_msgs = [m["content"] for m in history if m["role"] == "user"]
    last = user_msgs[-1] if user_msgs else ""
    if any(k in last for k in HIGH_KEYWORDS):
        return "high"
    recent = " ".join(user_msgs[-3:])
    hits = {k for k in MEDIUM_KEYWORDS if k in recent}
    if len(hits) >= 2:
        return "medium"
    return "low"


