def render_selfcare():
    st.info(
        "지금 마음이와 함께 해볼 수 있는 방법이에요. 힘든 마음이 이어지면 그때 의사 상담을 도와드릴게요.",
        icon=":material/self_improvement:",
    )
    with st.expander("1분 호흡", icon=":material/air:"):
        st.markdown("편한 자세로 앉아 어깨 힘을 빼 보세요. **4초 동안 코로 들이마시고, 6초 동안 천천히 내쉬어요.** 6번만 반복해 보세요.")
    with st.expander("주변 감각 찾기", icon=":material/visibility:"):
        st.markdown("눈에 보이는 것 **5가지**, 만져지는 것 **4가지**, 들리는 소리 **3가지**, 냄새 **2가지**, 맛 **1가지**를 천천히 찾아보세요. 생각이 지금 이 순간으로 돌아오는 데 도움이 돼요.")
    with st.expander("작은 행동 하나", icon=":material/check_circle:"):
        st.markdown("물 한 잔 마시기, 창문 열고 바람 쐬기, 집 앞 10분 걷기 중 **딱 하나만** 골라 해 보세요. 크게 하지 않아도 괜찮아요.")


def render_banner(step):
    step = {"high": "crisis", "medium": "doctor"}.get(step, step)  # 예전 대화 기록 호환
    if step == "crisis":
        st.error(
            "**지금 많이 힘드신 것 같아 걱정돼요.**\n\n"
            "자살예방상담전화 **109** (24시간)  |  긴급 **112 / 119**\n\n"
            "담당 의사님께도 알림이 전달되었어요. 혼자 견디지 마세요.",
            icon=":material/emergency:",
        )
    elif step == "doctor":
        st.warning(
            "요즘 힘든 마음이 이어지고 있어서, 담당 의사님과 이야기해 보면 도움이 될 수 있어요.",
            icon=":material/stethoscope:",
        )
    elif step == "self":
        render_selfcare()


# ============ 음성(TTS) ============
def clean_for_tts(text):
    t = re.sub(r"[\U00010000-\U0010ffff\u2600-\u27bf\u2b00-\u2bff\ufe0f\u200d]", "", text)
    t = re.sub(r"[*_`#>]", "", t)
    return re.sub(r"\s+", " ", t).strip()


async def _tts_async(text):
    comm = edge_tts.Communicate(text, VOICE, rate="-5%")
    buf = bytearray()
    async for chunk in comm.stream():
        if chunk["type"] == "audio":
            buf.extend(chunk["data"])
    return bytes(buf)


def make_voice(text, show_error=True):
    """텍스트 → mp3(base64). 실패하면 None"""
    t = clean_for_tts(text)
    if not t:
        return None
    try:
        with ThreadPoolExecutor(max_workers=1) as ex:
            audio = ex.submit(lambda: asyncio.run(_tts_async(t))).result(timeout=25)
        if not audio:
            return None
        return base64.b64encode(audio).decode()
    except Exception as e:
        if show_error:
            st.caption(f"(음성 생성 오류: {e})")
        return None


