def sprout_svg(stage, size=190):
    """마음 새싹이 자라는 7단계 (0 씨앗 ~ 6 꽃). 마음이 머리의 새싹과 같은 파스텔 블루 톤"""
    ink, fill, soft = "#6F8FD8", "#CFE0FF", "#EEF3FF"
    stage = max(0, min(6, int(stage)))

    def leaf(x, y, rx, ry, rot):
        return (f'<ellipse cx="{x:.1f}" cy="{y:.1f}" rx="{rx}" ry="{ry}" transform="rotate({rot} {x:.1f} {y:.1f})" '
                f'fill="{fill}" stroke="{ink}" stroke-width="2"/>')

    def spark(x, y, s, op=1):
        return (f'<path d="M12 2L14 10L22 12L14 14L12 22L10 14L2 12L10 10Z" transform="translate({x} {y}) scale({s})" '
                f'fill="#E3ECFF" stroke="{ink}" stroke-width="1.2" opacity="{op}"/>')

    base_y = 172
    h = [0, 22, 44, 64, 80, 90, 92][stage]
    top = base_y - h
    parts = [
        '<ellipse cx="100" cy="192" rx="64" ry="11" fill="#DCE6FF" opacity=".7"/>',
        '<path d="M46 192 Q100 146 154 192 Z" fill="#CBD9FF" stroke="#8EA6E6" stroke-width="2" stroke-linejoin="round"/>',
        '<path d="M70 184 Q100 168 130 184" fill="none" stroke="#B3C6F5" stroke-width="2" stroke-linecap="round" opacity=".7"/>',
    ]
    plant = []
    if stage == 0:
        plant.append(f'<ellipse cx="100" cy="171" rx="10" ry="6.5" fill="#fff" stroke="{ink}" stroke-width="2"/>')
        plant.append(spark(88, 128, 1.1, .9))
    else:
        plant.append(f'<path d="M100 {base_y} L100 {top}" stroke="{ink}" stroke-width="4" stroke-linecap="round"/>')
        lt = top + (12 if stage >= 5 else 0)           # 맨 위 잎 위치
        if stage == 1:
            plant += [leaf(91, lt + 2, 10, 5, 28), leaf(109, lt + 2, 10, 5, -28)]
        else:
            tr = 17 if stage == 2 else 19
            plant += [leaf(100 - tr * .85, lt + 4, tr, tr * .48, 30), leaf(100 + tr * .85, lt + 4, tr, tr * .48, -30)]
        if stage >= 3:
            my = top + h * .48
            plant += [leaf(86, my, 14, 7, 28), leaf(114, my, 14, 7, -28)]
        if stage >= 4:
            ly = top + h * .78
            plant += [leaf(88, ly, 12, 6, 24), leaf(112, ly, 12, 6, -24)]
        if stage == 5:
            plant.append(f'<ellipse cx="100" cy="{top - 8}" rx="9" ry="14" fill="{soft}" stroke="{ink}" stroke-width="2"/>')
            plant.append(f'<path d="M91 {top + 2} Q100 {top - 4} 109 {top + 2}" fill="none" stroke="{ink}" stroke-width="2"/>')
        if stage == 6:
            cy = top - 8
            import math
            for k in range(6):
                a = math.radians(k * 60)
                x, y = 100 + 15 * math.sin(a), cy - 15 * math.cos(a)
                plant.append(f'<ellipse cx="{x:.1f}" cy="{y:.1f}" rx="9" ry="15" transform="rotate({k * 60} {x:.1f} {y:.1f})" '
                             f'fill="{soft}" stroke="{ink}" stroke-width="2"/>')
            plant.append(f'<circle cx="100" cy="{cy}" r="9" fill="#BFE8FF" stroke="{ink}" stroke-width="2"/>')
            plant.append(spark(52, 70, .9, .9)); plant.append(spark(138, 56, .7, .8))
    body = (f'<g style="transform-origin:100px {base_y}px;animation:sproutsway 4.5s ease-in-out infinite">'
            + "".join(plant) + '</g>')
    return (f'<svg viewBox="0 36 200 174" width="{size}" height="{int(size * 174 / 200)}" xmlns="http://www.w3.org/2000/svg" '
            f'style="display:block;margin:0 auto;">' + "".join(parts) + body + '</svg>')



def load_garden():
    try:
        with open(GARDEN_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def save_garden(data):
    with open(GARDEN_FILE, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)


def wearable_effective():
    """새싹 계산용 웨어러블 데이터 (시연 스위치를 켜면 오늘 목표 달성으로 처리)"""
    df = WEARABLE.copy()
    if st.session_state.get("demo_goals"):
        i = df.index[-1]
        df.loc[i, "sunlight_min"] = 12
        df.loc[i, "steps"] = 3400
        df.loc[i, "sleep_hours"] = 6.5
    return df


def garden_snapshot():
    """오늘까지의 햇살·단계를 계산하고, 앱 활동(대화·돌아보기)을 자동 기록해요."""
    g = load_garden()
    pid = PATIENT["id"]
    is_new = pid not in g
    rec = g.setdefault(pid, {"days": {}, "seen_stage": 0})
    today = date.today().isoformat()
    ids = rec["days"].setdefault(today, [])
    changed = is_new

    if any(m["role"] == "user" for m in st.session_state.messages) and "talk" not in ids:
        ids.append("talk"); changed = True
    if any(c.get("time", "")[:10] == today for c in phq_history()) and "reflect" not in ids:
        ids.append("reflect"); changed = True

    df = wearable_effective()
    row = df.iloc[-1]
    auto_total = int((df["sunlight_min"] >= 10).sum() + (df["steps"] >= 3000).sum() + (df["sleep_hours"] >= 6).sum())
    extra_total = sum(GARDEN_WEIGHT.get(i, 0) for day_ids in rec["days"].values() for i in set(day_ids))
    total = auto_total + extra_total + st.session_state.demo_rays
    stage = max(i for i, (th, _, _) in enumerate(GARDEN_STAGES) if total >= th)

    leveled = None
    if is_new:
        rec["seen_stage"] = stage
    elif stage > rec.get("seen_stage", 0):
        leveled = stage; rec["seen_stage"] = stage; changed = True
    elif stage < rec.get("seen_stage", 0):
        rec["seen_stage"] = stage; changed = True      # 시연 슬라이더를 내린 경우에만 해당
    if changed:
        save_garden(g)

    today_auto = int(row["sunlight_min"] >= 10) + int(row["steps"] >= 3000) + int(row["sleep_hours"] >= 6)
    today_extra = sum(GARDEN_WEIGHT.get(i, 0) for i in set(ids))
    return {"row": row, "ids": set(ids), "total": total, "stage": stage, "leveled": leveled,
            "today_rays": today_auto + today_extra}


def mark_done(action_id):
    g = load_garden()
    rec = g.setdefault(PATIENT["id"], {"days": {}, "seen_stage": 0})
    ids = rec["days"].setdefault(date.today().isoformat(), [])
    if action_id not in ids:
        ids.append(action_id)
    save_garden(g)
    st.session_state.voice = {"id": st.session_state.voice.get("id", 0) + 1, "b64": None, "mood": "happy"}


def act_row(ico, name, sub, pct, done, chip=None, chip_cls="chip-info"):
    chip_html = f"<span class='chip {chip_cls}'>{chip}</span>" if chip else ""
    return (
        "<div class='act'>"
        f"<div class='act-ico{' done' if done else ''}'>{icon(ico, 20, '#FFFFFF' if done else '#4F6BD3')}</div>"
        f"<div class='act-main'><div class='act-name'>{name}</div><div class='act-sub'>{sub}</div>"
        f"<div class='mini'><i style='width:{pct}%'></i></div></div>{chip_html}</div>"
    )


